--
-- Name: guard_excessive_updates(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.guard_excessive_updates() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$ DECLARE record_count integer; max_record_count integer; BEGIN SELECT count(*) FROM oldtbl INTO record_count; max_record_count := COALESCE(setting_as_int('inst.max_update_limit.' || TG_TABLE_NAME), setting_as_int('inst.max_update_limit'), '1000'); IF record_count > max_record_count THEN IF current_setting('inst.max_update_fail', true) IS NOT DISTINCT FROM 'true' THEN RAISE EXCEPTION 'guard_excessive_updates: % to %.% failed', TG_OP, TG_TABLE_SCHEMA, TG_TABLE_NAME USING DETAIL = 'Would update ' || record_count || ' records but max is ' || max_record_count || ', orig query: ' || current_query(); ELSE RAISE WARNING 'guard_excessive_updates: % to %.% was dangerous', TG_OP, TG_TABLE_SCHEMA, TG_TABLE_NAME USING DETAIL = 'Updated ' || record_count || ' records but threshold is ' || max_record_count || ', orig query: ' || current_query(); END IF; END IF; RETURN NULL; END $$;


ALTER FUNCTION public.guard_excessive_updates() OWNER TO postgres;

--
-- Name: half_md5_as_bigint(character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.half_md5_as_bigint(strand character varying) RETURNS bigint
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
  DECLARE
    strand_md5 bytea;
  BEGIN
    strand_md5 := decode(md5(strand), 'hex');
    RETURN (CAST(get_byte(strand_md5, 0) AS bigint) << 56) +
                              (CAST(get_byte(strand_md5, 1) AS bigint) << 48) +
                              (CAST(get_byte(strand_md5, 2) AS bigint) << 40) +
                              (CAST(get_byte(strand_md5, 3) AS bigint) << 32) +
                              (CAST(get_byte(strand_md5, 4) AS bigint) << 24) +
                              (get_byte(strand_md5, 5) << 16) +
                              (get_byte(strand_md5, 6) << 8) +
                               get_byte(strand_md5, 7);
  END;
  $$;


ALTER FUNCTION public.half_md5_as_bigint(strand character varying) OWNER TO postgres;

--
-- Name: pseudonyms_before_insert_or_update_enforce_unique_across_auth_p(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pseudonyms_before_insert_or_update_enforce_unique_across_auth_p() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  auth_type TEXT;
BEGIN
  IF (OLD.authentication_provider_id IS DISTINCT FROM NEW.authentication_provider_id OR
      OLD.unique_id_normalized IS DISTINCT FROM NEW.unique_id_normalized OR
      OLD.account_id IS DISTINCT FROM NEW.account_id OR
      OLD.workflow_state IS DISTINCT FROM NEW.workflow_state) AND
      NEW.workflow_state <> 'deleted' THEN
    IF NEW.authentication_provider_id IS NOT NULL THEN
      SELECT ap.auth_type
      INTO auth_type
      FROM authentication_providers ap
      WHERE ap.id = NEW.authentication_provider_id;
    ELSE
      auth_type := NULL;
    END IF;

    IF auth_type IN ('cas', 'saml', 'canvas', 'ldap') THEN
      IF EXISTS (
        SELECT 1
        FROM pseudonyms p
        WHERE p.unique_id_normalized = NEW.unique_id_normalized
          AND p.account_id = NEW.account_id
          AND p.workflow_state <> 'deleted'
          AND p.authentication_provider_id IS NULL
          AND p.id <> NEW.id
      ) THEN
        RAISE EXCEPTION 'duplicate unique_id_normalized found against unassociated pseudonyms'
        USING ERRCODE = '23505',
        DETAIL = format('Key (unique_id_normalized, account_id)=(%s, %s) already exists.', NEW.unique_id_normalized, NEW.account_id);
      END IF;
    ELSIF auth_type IS NULL THEN
      IF EXISTS (
        SELECT 1
        FROM pseudonyms p
        JOIN authentication_providers ap ON ap.id = p.authentication_provider_id
        WHERE p.unique_id_normalized = NEW.unique_id_normalized
          AND p.account_id = NEW.account_id
          AND p.workflow_state <> 'deleted'
          AND ap.auth_type IN ('cas', 'saml', 'canvas', 'ldap')
          AND p.id <> NEW.id
      ) THEN
        RAISE EXCEPTION 'duplicate unique_id_normalized found for unassociated pseudonym'
        USING ERRCODE = '23505',
        DETAIL = format('Key (unique_id_normalized, account_id)=(%s, %s) already exists.', NEW.unique_id_normalized, NEW.account_id);
      END IF;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.pseudonyms_before_insert_or_update_enforce_unique_across_auth_p() OWNER TO postgres;

--
-- Name: setting_as_int(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.setting_as_int(p_setting text) RETURNS integer
    LANGUAGE plpgsql
    AS $_$ DECLARE v_text text; v_int8 int8; BEGIN v_text := current_setting( p_setting, true ); IF v_text IS NULL THEN RETURN NULL; END IF; IF NOT v_text ~ '^-?[0-9]{1,10}$' THEN RETURN NULL; END IF; v_int8 := v_text::INT8; IF v_int8 > 2147483647 OR v_int8 < -2147483648 THEN RETURN NULL; END IF; RETURN v_int8::int4; END; $_$;


ALTER FUNCTION public.setting_as_int(p_setting text) OWNER TO postgres;

--
-- Name: submission_comment_after_delete_set_last_comment_at__tr_fn(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.submission_comment_after_delete_set_last_comment_at__tr_fn() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE submissions
  SET last_comment_at = (
     SELECT MAX(submission_comments.created_at) FROM submission_comments
      WHERE submission_comments.submission_id=submissions.id AND
      submission_comments.author_id <> submissions.user_id AND
      submission_comments.draft <> 't' AND
      submission_comments.provisional_grade_id IS NULL
  ) WHERE id = OLD.submission_id;
  RETURN OLD;
END;
$$;


ALTER FUNCTION public.submission_comment_after_delete_set_last_comment_at__tr_fn() OWNER TO postgres;

--
-- Name: submission_comment_after_save_set_last_comment_at__tr_fn(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.submission_comment_after_save_set_last_comment_at__tr_fn() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE submissions
  SET last_comment_at = (
     SELECT MAX(submission_comments.created_at) FROM submission_comments
      WHERE submission_comments.submission_id=submissions.id AND
      submission_comments.author_id <> submissions.user_id AND
      submission_comments.draft <> 't' AND
      submission_comments.provisional_grade_id IS NULL
  ) WHERE id = NEW.submission_id;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.submission_comment_after_save_set_last_comment_at__tr_fn() OWNER TO postgres;

